import{_ as a,o,c as r,a2 as t}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"Cómo protegemos tus datos","description":"","frontmatter":{},"headers":[],"relativePath":"privacidad/index.md","filePath":"privacidad/index.md","lastUpdated":1791064393000}'),s={name:"privacidad/index.md"};function n(i,e,u,l,d,c){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="como-protegemos-tus-datos" tabindex="-1">Cómo protegemos tus datos <a class="header-anchor" href="#como-protegemos-tus-datos" aria-label="Permalink to &quot;Cómo protegemos tus datos&quot;">​</a></h1><p>Aquí explicamos qué hacemos con los datos, sin letra pequeña. Si algo de lo que decimos aquí no coincide con el código, el código (que es público) manda, y queremos saberlo.</p><h2 id="lo-que-prometemos" tabindex="-1">Lo que prometemos <a class="header-anchor" href="#lo-que-prometemos" aria-label="Permalink to &quot;Lo que prometemos&quot;">​</a></h2><ol><li><strong>Nunca guardamos números de teléfono.</strong> Guardamos un código calculado a partir del número con una clave secreta (HMAC-SHA256). Si alguien robara la base de datos, no obtendría números.</li><li><strong>Tu agenda no se guarda como agenda.</strong> Nadie puede ver &quot;los contactos de una persona&quot;.</li><li><strong>Un nombre solo se muestra si al menos 3 personas distintas lo guardaron igual.</strong></li><li><strong>Nadie puede buscar a una persona por su nombre.</strong> Solo ves un nombre si ya tienes el número, porque te llamó.</li><li><strong>Los nombres se guardan cifrados</strong> con una clave que depende de cada número.</li><li><strong>No guardamos quién consultó qué número.</strong> El historial de llamadas vive solo en tu teléfono.</li><li><strong>Puedes retirar tu aporte y borrar tu cuenta cuando quieras.</strong> Cualquier persona puede pedir que se oculte el nombre asociado a su número.</li></ol><h2 id="lo-que-no-prometemos-y-por-que" tabindex="-1">Lo que no prometemos (y por qué) <a class="header-anchor" href="#lo-que-no-prometemos-y-por-que" aria-label="Permalink to &quot;Lo que no prometemos (y por qué)&quot;">​</a></h2><p>No decimos que sea &quot;imposible&quot; saber un número a partir de su código. Hay pocos números de teléfono posibles, así que quien tenga la <strong>clave secreta</strong> podría calcular los códigos de todos y compararlos. Por eso la clave se guarda fuera de la base de datos y se protege como lo más importante del sistema.</p><h2 id="tu-cuenta" tabindex="-1">Tu cuenta <a class="header-anchor" href="#tu-cuenta" aria-label="Permalink to &quot;Tu cuenta&quot;">​</a></h2><ul><li>Te registras con correo y contraseña (y pronto con Google) a través de Firebase Authentication.</li><li><strong>Tu número de teléfono no se vincula a tu cuenta.</strong></li><li>Guardamos la fecha en que aceptaste los términos y qué versión aceptaste, como exige la ley.</li></ul><h2 id="aportar-tu-agenda" tabindex="-1">Aportar tu agenda <a class="header-anchor" href="#aportar-tu-agenda" aria-label="Permalink to &quot;Aportar tu agenda&quot;">​</a></h2><p>Es <strong>opcional</strong>; la app funciona igual sin aportar.</p><p>Si decides aportar:</p><ul><li>La app envía los números y nombres por una conexión cifrada.</li><li>El servidor convierte cada número en su código y cifra cada nombre. Nunca guarda el número.</li><li>Los nombres que describen una relación (&quot;Mamá&quot;, &quot;Mi amor&quot;, &quot;Jefe&quot;) <strong>no se usan</strong>; solo cuenta que alguien tiene ese número guardado.</li><li>Cada aporte se registra con un identificador que no está ligado directamente a tu cuenta.</li><li>Puedes <strong>dejar de aportar</strong> en Ajustes: se borra todo lo que aportaste.</li></ul><h2 id="lo-que-se-queda-en-tu-telefono" tabindex="-1">Lo que se queda en tu teléfono <a class="header-anchor" href="#lo-que-se-queda-en-tu-telefono" aria-label="Permalink to &quot;Lo que se queda en tu teléfono&quot;">​</a></h2><ul><li>Tu lista de números bloqueados.</li><li>Tus ajustes de bloqueo.</li><li>El historial de llamadas (30 días, máximo 200).</li><li>Una caché de consultas recientes (24 horas), para identificar más rápido a quien vuelve a llamar.</li></ul><h2 id="tus-derechos" tabindex="-1">Tus derechos <a class="header-anchor" href="#tus-derechos" aria-label="Permalink to &quot;Tus derechos&quot;">​</a></h2><p>Puedes conocer, actualizar, rectificar y suprimir tus datos, y revocar tu autorización. Desde la app:</p><ul><li><strong>Cuenta → Ver qué datos guardamos.</strong></li><li><strong>Cuenta → Borrar mi cuenta</strong>: borra tu cuenta, tus reportes y tus aportes.</li></ul><p>Si no tienes cuenta y tu número aparece mal identificado, mira <a href="/Tranqui/guia/apelacion">¿Tu número aparece mal?</a>.</p><p>Los detalles legales están en la <a href="/Tranqui/legal/politica-de-tratamiento">Política de tratamiento de datos</a>.</p>',19)])])}const q=a(s,[["render",n]]);export{p as __pageData,q as default};
